use std::marker::PhantomData;

use serde::Serialize;

use crate::builder::Island;

/// A typed island definition that maps a static name to a props struct.
///
/// Created by the `#[island]` attribute macro. The type parameter `P`
/// is the generated props struct (e.g. `CounterProps`).
///
/// # Example
///
/// ```ignore
/// // Generated by #[island]
/// pub static Counter: IslandDef<CounterProps> = IslandDef::new("Counter");
///
/// // Usage
/// Counter.island(CounterProps { initial_count: 5.0, label: "Clicks".into(), disabled: None })
/// ```
pub struct IslandDef<P: Serialize = ()> {
    name: &'static str,
    _marker: PhantomData<fn(P)>,
}

impl<P: Serialize> IslandDef<P> {
    /// Create a new island definition with the given name.
    ///
    /// This is `const` so it can be used in `static` items.
    pub const fn new(name: &'static str) -> Self {
        Self {
            name,
            _marker: PhantomData,
        }
    }

    /// Build an `Island` with typed, serialized props.
    pub fn island(&self, props: P) -> Island {
        Island::new(self.name).props_from_serialize(&props)
    }

    /// Get the island name.
    pub const fn name(&self) -> &'static str {
        self.name
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[derive(Serialize)]
    struct TestProps {
        count: f64,
        label: String,
    }

    #[test]
    fn island_def_is_const() {
        const DEF: IslandDef<TestProps> = IslandDef::new("Test");
        assert_eq!(DEF.name(), "Test");
    }

    #[test]
    fn island_def_creates_island() {
        let def: IslandDef<TestProps> = IslandDef::new("Counter");
        let _island = def.island(TestProps {
            count: 42.0,
            label: "Hello".into(),
        });
        // Island was created without panic — props were serialized
    }

    #[test]
    fn island_def_renders_with_props() {
        use proa_core::ctx::Ctx;

        let def: IslandDef<TestProps> = IslandDef::new("Counter");
        let island = def.island(TestProps {
            count: 5.0,
            label: "Clicks".into(),
        });

        let mut cx = Ctx::new();
        island.render(&mut cx).unwrap();

        let html = String::from_utf8(cx.into_output().into_vec()).unwrap();
        assert!(html.contains(r#"data-island="Counter""#));
        assert!(html.contains(r#""count":5"#));
        assert!(html.contains(r#""label":"Clicks""#));
    }
}
